import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.BbQrW5_t.js";const h=JSON.parse('{"title":"漏洞研究方向","description":"","frontmatter":{"title":"漏洞研究方向","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","高级"]},"headers":[],"relativePath":"study/cyber-security/chapters/高级篇/02-漏洞研究方向.md","filePath":"study/cyber-security/chapters/高级篇/02-漏洞研究方向.md","lastUpdated":1788493831000}'),i={name:"study/cyber-security/chapters/高级篇/02-漏洞研究方向.md"};function l(p,a,o,r,d,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="_02-·-漏洞研究方向——从使用者到发现者" tabindex="-1">02 · 漏洞研究方向——从使用者到发现者 <a class="header-anchor" href="#_02-·-漏洞研究方向——从使用者到发现者" aria-label="Permalink to &quot;02 · 漏洞研究方向——从使用者到发现者&quot;">​</a></h1><blockquote><p>前两年你是漏洞的&quot;使用者&quot;；这个方向让你成为&quot;发现者&quot;。核心竞争力：源码/补丁的<strong>深度阅读</strong>——这恰是资深工程师的舒适区。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>建立 CVE 复现的工程化模板（容器化+报告化）</li><li>掌握补丁 diff 分析法</li><li>跑通一次 Fuzzing 最小闭环</li><li>说清负责任披露（CVD）流程</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_2-1-cve-复现工程化-你的第一个复现库" tabindex="-1">2.1 CVE 复现工程化（你的第一个复现库） <a class="header-anchor" href="#_2-1-cve-复现工程化-你的第一个复现库" aria-label="Permalink to &quot;2.1 CVE 复现工程化（你的第一个复现库）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cve-lab/</span></span>
<span class="line"><span>├── CVE-2021-44228-Log4Shell/</span></span>
<span class="line"><span>│   ├── docker-compose.yml     # 漏洞环境一键起</span></span>
<span class="line"><span>│   ├── poc.py                 # 参数化 PoC（第 1 年 04 的规范）</span></span>
<span class="line"><span>│   ├── README.md              # 漏洞原理/影响版本/复现步骤/修复分析</span></span>
<span class="line"><span>│   └── notes.md               # 调试过程（失败了什么、为什么）</span></span></code></pre></div><p>复现是&quot;最便宜的漏洞研究教育&quot;：每个 CVE 教你一个&quot;新的代码模式如何变危险&quot;。目标节奏：2 周 1 个 → 年底 25 个入库（每篇复现=一篇博客，你的知识库直接滚动增长）。</p><h3 id="_2-2-补丁-diff-分析法-系统化" tabindex="-1">2.2 补丁 diff 分析法（系统化） <a class="header-anchor" href="#_2-2-补丁-diff-分析法-系统化" aria-label="Permalink to &quot;2.2 补丁 diff 分析法（系统化）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 来源：GitHub Advisory / 厂商公告 / NVD</span></span>
<span class="line"><span>2. 拿到 fix commit → 只看三类变更：</span></span>
<span class="line"><span>   a) 新增校验/过滤 → 原缺陷类型（说明当初信任了什么）</span></span>
<span class="line"><span>   b) 类型/解析方式变更（String→URI）→ 原解析被滥用</span></span>
<span class="line"><span>   c) 依赖升级 → 传递漏洞</span></span>
<span class="line"><span>3. 反推 PoC：变更语义 = &quot;原来允许 X，现在不允许&quot; → 构造 X</span></span>
<span class="line"><span>4. 检查同类代码：grep 同模式 → 疑似同族漏洞（1-day 逻辑的捷径）</span></span></code></pre></div><p>实例思维：某 SSRF 修复把 <code>new URL(input)</code> 换成了白名单校验 → 反推原版本信任完整 URL → 测试 DNS rebinding/重定向绕过历史缺口。</p><h3 id="_2-3-fuzzing-入门-afl-最小闭环" tabindex="-1">2.3 Fuzzing 入门（AFL 最小闭环） <a class="header-anchor" href="#_2-3-fuzzing-入门-afl-最小闭环" aria-label="Permalink to &quot;2.3 Fuzzing 入门（AFL 最小闭环）&quot;">​</a></h3><p>原理：覆盖率导向变异——记录输入覆盖了哪些分支，<strong>优先变异&quot;走得最远&quot;的输入</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：一个解析输入文件的程序（如 图片/配置 解析器）</span></span>
<span class="line"><span>1. 用 afl-gcc/afl-clang-fast 重编译目标（插桩）</span></span>
<span class="line"><span>2. 准备种子语料（正常样例文件）</span></span>
<span class="line"><span>3. afl-fuzz -i seeds -o out ./target @@</span></span>
<span class="line"><span>4. 看 crashes/ 目录 → 每个崩溃样本 → gdb 定位 → 判定可利用性</span></span></code></pre></div><p>认知要点：Fuzzing 强在&quot;找内存破坏与解析缺陷&quot;，弱在&quot;逻辑漏洞&quot;（它不懂业务）。工程时间分配：Fuzzing 后台跑，人工 diff 分析前台做。</p><h3 id="_2-4-从研究到披露-cvd-负责任流程" tabindex="-1">2.4 从研究到披露（CVD 负责任流程） <a class="header-anchor" href="#_2-4-从研究到披露-cvd-负责任流程" aria-label="Permalink to &quot;2.4 从研究到披露（CVD 负责任流程）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发现问题 → 本地确认可复现 → 判断影响与可利用性</span></span>
<span class="line"><span>→ 联系厂商（安全邮箱/PSIRT）→ 给出 90 天修复窗口</span></span>
<span class="line"><span>→ 厂商修复发版 → CVE 编号申请（MITRE/厂商 CNA）</span></span>
<span class="line"><span>→ 协调发布：报告+补丁同日公开</span></span></code></pre></div><p>红线：<strong>未协调公开 = 可能违法（提供侵入工具/破坏秩序）</strong>；细节在补丁发布前不披露、不留底、不分享。</p><h3 id="_2-5-目标产出-第-3-年" tabindex="-1">2.5 目标产出（第 3 年） <a class="header-anchor" href="#_2-5-目标产出-第-3-年" aria-label="Permalink to &quot;2.5 目标产出（第 3 年）&quot;">​</a></h3><ul><li>1 个 CVE 编号 或 1 篇高质量漏洞分析（先知社区/个人博客）</li><li>25+ 复现库（GitHub 展示=简历硬资产）</li><li>1 个 Fuzzing 产出（crash 分析报告）</li></ul><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><p>选一个&quot;修复已完整披露&quot;的经典 CVE（如 Fastjson/Log4j 系）按 2.1 模板完成复现全流程：环境→PoC→修复 diff 分析→博客。</p><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>只复现不复现&quot;为什么&quot;——原理笔记才是资产</li><li>Fuzzing 无种子工程——种子质量决定覆盖</li><li>对未修复漏洞&quot;顺手深挖&quot;——法律红线，披露流程才是护身符</li><li>复现环境乱堆——目录规范+容器化，否则三个月后自己看不懂</li><li>忽视&quot;同类代码 grep&quot;——漏洞常成族出现，这是效率密码</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 为什么复现要先容器化？</summary><p>可复现性+可抛弃性：环境依赖锁死在 compose 文件里，任何人（含未来的你）一键重建；用完即弃不污染宿主机。</p></details><details><summary>2. 补丁 diff 里&quot;新增白名单&quot;透露什么？</summary><p>原实现对输入来源做了信任假设；白名单枚举的值域往往就是攻击者可控面——按语义反推 PoC 输入空间。</p></details><details><summary>3. Fuzzing 为什么找不到逻辑漏洞？</summary><p>逻辑漏洞的&quot;错误&quot;不是内存/崩溃层面，而是&quot;业务上不该允许&quot;——没有可自动判定的 oracle，只有理解业务的人能判断。</p></details><details><summary>4. 90 天披露窗口的意义？</summary><p>给厂商合理修复时间的同时设定明确期限，防止无限拖延；对研究者是保护（协调披露=合法身份）。</p></details><details><summary>5. &quot;同类代码 grep&quot;为什么是 1-day 捷径？</summary><p>开发者常复制粘贴同一模式；一处漏洞的&quot;模式签名&quot;在代码库中往往多处存在，一处修复常漏同族。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>第3年 W109-W116</strong>；资源：AFL 官方文档、GitHub Advisory Database、《0day 安全》概念篇</li></ul>`,32)])])}const q=s(i,[["render",l]]);export{h as __pageData,q as default};
